  ui_story_31170401_X49_dialog_content = "Próximo é colher ervilhas!",
  ui_story_31170401_50_dialog_content = "Meus ombros estão tão doloridos...",
  ui_story_31170401_51_dialog_content = "As crianças de hoje em dia realmente deixam a desejar quando se trata de treinamento físico. Olhe para você! Mal começamos e seus braços já estão tremendo como as pernas de um filhote de cervo!",
  ui_story_31170401_52_dialog_content = "Não pare ainda! Você ainda tem todas essas ervilhas para colher, agora apresse-se!",
  ui_story_31170401_53_dialog_content = "Mas há muitos deles! Muito mais do que uma única pessoa pode lidar...",
  ui_story_31170401_54_dialog_content = "O inimigo não vai tolerar todas as suas reclamações e desculpas em uma batalha real.",
  ui_story_31170401_55_dialog_content = "Você tem razão, mas ainda assim...",
  ui_story_31170401_56_dialog_content = "Você precisa acreditar em si mesmo... na sua tenacidade e perseverança! Lembre-se, você deu sua palavra de que terminaria isso!",
  ui_story_31170401_57_dialog_content = "Agora comece a colher e não deixe nada ser desperdiçado!",
  ui_story_31170401_58_dialog_content = "*Soluçando* Por que eu tenho que fazer isso...?",
  ui_story_31170401_59_dialog_content = "Se eu soubesse que era isso que eu tinha que fazer, não teria concordado em fazer os testes dele... Eu só não estava com apetite, só isso...",
  ui_story_31170401_60_dialog_content = "Você ainda tem cinco pedaços de carne sobrando! Continue cortando!",
  ui_story_31170401_61_dialog_content = "Que tipo de teste é esse, Gram?! Você está apenas me fazendo fazer seu trabalho nesse ponto, não é?!",
