  ui_story_31170401_65_dialog_content = "Graças a todos os testes que fizemos agora, consegui entender completamente a condição atual do seu corpo e preparei isso para você.",
  ui_story_31170401_66_dialog_content = "Aqui.",
  ui_story_31170401_67_dialog_content = "Arroz frito com carne e ervilhas...?",
  ui_story_31170401_68_dialog_content = "(Borbulhar, borbulhar)",
  ui_story_31170401_69_dialog_content = "Parece que seu apetite voltou. Por que não leva isso para o seu quarto...",
  ui_story_31170401_70_dialog_content = "*mastigar*",
  ui_story_31170401_71_dialog_content = "Delicioso!!",
  ui_story_31170401_72_dialog_content = "Como pode algo tão delicioso existir no mundo?! A carne está frita perfeitamente!",
  ui_story_31170401_73_dialog_content = "A carne é gordurosa, mas não muito oleosa, as ervilhas são crocantes e saborosas, e cada grão de arroz torrado se destaca perfeitamente dos outros...",
  ui_story_31170401_74_dialog_content = "*mastigar*",
  ui_story_31170401_75_dialog_content = "Ou você pode simplesmente comê-lo aqui. Parece que minhas palavras não estão te alcançando no momento, de qualquer forma.",
  ui_story_31170401_76_dialog_content = "*Devorar* Como... Como algo pode ter um sabor tão incrível...?! *Mastigar*",
  ui_story_31170401_77_dialog_content = "Ei, vá mais devagar. Não fale de boca cheia!",
  ui_story_31170401_78_dialog_content = "*Arroto*",
  ui_story_31170401_79_dialog_content = "Você realmente fez aquele arroz frito, Gram? *Arroto* Eu não fazia ideia... que você era um mestre cozinheiro tão incrível!",
  ui_story_31170401_80_dialog_content = "Hahaha! Passei muitos anos da minha vida militar trabalhando nos refeitórios, garoto! Isso não foi nada, tenho certeza de que já alimentei todas as pessoas das Cidades Subterrâneas pelo menos uma vez!",
  ui_story_31170401_81_dialog_content = "Eu nunca teria imaginado... *Glup*",
  ui_story_31170401_82_dialog_content = "Cof... Fico feliz que você gostou, mas não precisa realmente lamber o prato até ficar limpo.",
  ui_story_31170401_83_dialog_content = "Ah, certo! Quando devo tomar meu remédio, Gram?",
  ui_story_31170401_84_dialog_content = "Seu remédio, huh... Falaremos sobre isso amanhã.",
  ui_story_31170401_85_dialog_content = "Por enquanto, que tal tomar um banho e dormir um pouco mais?",
  ui_story_31170401_86_dialog_content = "Bem, estou me sentindo bastante cansado... Vou fazer isso então, Gram.",
  ui_story_31170401_87_dialog_content = "Bom Dia, PlayerName!",
  ui_story_31170401_88_dialog_content = "Ei, Vice! Bom dia!",
  ui_story_31170401_89_dialog_content = "Você acordou cedo hoje, PlayerName. Está se sentindo melhor?",
  ui_story_31170401_90_dialog_content = "Bom dia, Gram.",
  ui_story_31170401_91_dialog_content = "Sim, muito melhor! Quando eu acordei esta manhã, me senti tão desperto e cheio de energia. Acho que não preciso tomar nenhum remédio hoje!",
  ui_story_31170401_92_dialog_content = "Os jovens realmente se recuperam rápido... Parece que minha cura funcionou, afinal!",
  ui_story_31170401_93_dialog_content = "Hã?",
  ui_story_31170401_94_dialog_content = "Resumindo, você tomou seu remédio ontem. Entendeu?",
  ui_story_31170401_95_option_content = "Sim, eu sei.",
  ui_story_31170401_96_dialog_content = "Os testes de ontem, eles foram trabalho e exercícios também, não foram?",
  ui_story_31170401_97_dialog_content = "E quando nos sentamos para comer... isso foi por volta da hora do jantar, não foi?",
  ui_story_31170401_98_dialog_content = "Cansado e cheio, adormeci assim que me deitei na cama... e fiquei dormindo por oito horas inteiras.",
  ui_story_31170401_99_dialog_content = "Isso significa que <color=#FFB400>a melhor cura é exercício regular e uma boa rotina diária</color>!",
  ui_story_31170401_100_option_content = "Na verdade não...",
  ui_story_31170401_101_dialog_content = "(Ahem) Você se lembra a que horas jantou?",
  ui_story_31170401_102_dialog_content = "Acho que foi tarde da tarde...",
  ui_story_31170401_103_dialog_content = "Aqueles testes que você fez durante o dia... na verdade, eram apenas trabalho físico.",
  ui_story_31170401_104_dialog_content = "Adicione um jantar saudável e uma boa noite de descanso, e você estará de volta ao seu eu normal!",
  ui_story_31170401_105_dialog_content = "Entendi... Agora compreendo! <color=#FFB400>A melhor cura é exercício regular e uma boa rotina diária</color>.",
  ui_story_31170401_106_dialog_content = "Isso mesmo!",
  ui_story_31170401_107_dialog_content = "Obrigado, Gram!",
  ui_story_31170401_108_dialog_content = "Estou feliz que você esteja se sentindo melhor. Lembre-se de que seu corpo é sua responsabilidade, mas não esqueça que outras pessoas também estão contando com você.",
  ui_story_31170401_109_dialog_content = "Especialmente quando se trata de batalha. Pelo bem dos seus amigos, você não pode deixar seu corpo voltar àquele estado. Entendido?",
  ui_story_31170401_110_option_content = "Entendido!",
  ui_story_31170401_111_dialog_content = "Se eu me deixar ficar tão cansado e fraco, isso pode afetar seriamente minha capacidade de dar ordens.",
  ui_story_31170401_112_dialog_content = "Nesse caso, até mesmo o menor erro pode custar caro. O preço pode até mesmo ser pago em sangue...",
  ui_story_31170401_113_dialog_content = "Você está certo... Vou cuidar melhor de mim mesmo a partir de agora!",
  ui_story_31170401_114_option_content = "Mas por quê?",
  ui_story_31170401_115_dialog_content = "Você está encarregado de nos comandar na batalha, lembra?",
  ui_story_31170401_116_dialog_content = "Se algo der errado... É possível que...",
  ui_story_31170401_117_dialog_content = "Isso poderia ter consequências sérias.",
  ui_story_31170401_118_dialog_content = "Entendi agora. Não vou deixar-me ficar naquele estado nunca mais.",
  ui_story_31170401_119_dialog_content = "Contanto que você entenda.",
  ui_story_31170401_120_dialog_content = "Agora, já que você está bem e curado, acho que é hora de eu me despedir.",
  ui_story_31170401_121_dialog_content = "Ele saiu tão rápido... Eu nem tive a chance de agradecer direito ainda.",
  ui_story_31170401_122_dialog_content = "Gram não é do tipo que aceita gratidão assim. Contanto que você esteja se sentindo melhor, isso já é mais do que suficiente para ele.",
  ui_story_31170401_123_dialog_content = "Não se deixe enganar pela atitude desleixada dele. Ele é extremamente atento ao bem-estar de seus amigos.",
  ui_story_31170401_124_dialog_content = "O <color=#FFB400>Arroz Frito do Soldado</color> que ele fez para você ontem é o melhor prato dele. É cheio de nutrientes e super saudável também!",
  ui_story_31170401_125_dialog_content = "Então é isso que se chama... Estava tão delicioso! Acho que nunca vou esquecer o sabor...",
  ui_story_31170401_126_dialog_content = "Antes de ele cozinhar aquele prato para mim, eu achava que Gram era apenas um veterano comum que atuava como gerente de logística.",
  ui_story_31170401_127_dialog_content = "Ele tem uma história tão longa e cheia de acontecimentos... Quando entrou no exército, serviu como cozinheiro por alguns anos antes de se juntar à linha defensiva para combater os ataques dos Eclipsitas...",
  ui_story_31170401_128_dialog_content = "Após se aposentar do exército, ele começou a trabalhar em logística, onde também redescobriu seu amor pela culinária. Todos esses anos de experiência e treinamento... É incrível!",
  ui_story_31170401_129_dialog_content = "Mas o Arroz Frito do Soldado é reservado para os doentes. Eu também só comi uma vez na minha vida.",
  ui_story_31170401_130_dialog_content = "Até pensei em ficar acordado até tarde nos próximos dias, só para que ele fizesse isso para mim novamente...",
  ui_story_31170401_131_dialog_content = "Acha que vale a pena, PlayerName?",
  ui_story_31170401_132_dialog_content = "Eu-Eu acho que não...",
  ui_story_31170401_133_dialog_content = "O Arroz Frito do Soldado pode até ser delicioso, mas aqueles testes foram muito exaustivos...",
  ui_story_31170601_1_dialog_content = "<color=#e8d9bb>Splish, splash—</color>",
  ui_story_31170601_2_dialog_content = "Não, só espera! Eu ainda não vou cair—",
  ui_story_31170601_3_dialog_content = "<size=45>Não vou cair—Aaaaahhh!</size>",
  ui_story_31170601_4_dialog_content = "<size=45>NÃOOOO—</size>",
  ui_story_31170601_5_dialog_content = "<size=45>Aaaaahhh—</size>",
  ui_story_31170601_6_dialog_content = "<color=#e8d9bb>Há quinze minutos</color>",
  ui_story_31170601_7_dialog_content = "<color=#e8d9bb>Splish, splash—</color>",
  ui_story_31170601_8_dialog_content = "Ah, que ar refrescante. Faz muito tempo que não visito um vale tão sereno e bonito como este.",
  ui_story_31170601_9_dialog_content = "Mas é o nosso destino final? Eu pensei que era treinamento? Ou...",
  ui_story_31170601_10_dialog_content = "Você finalmente está mostrando compaixão e aproveitando a oportunidade para me levar para passear?",
  ui_story_31170601_11_dialog_content = "<color=#e8d9bb>Splash!</color>",
  ui_story_31170601_12_dialog_content = "Gram?!",
  ui_story_31170601_13_dialog_content = "O-Onde você está? Você não caiu acidentalmente no lago, caiu? Não me assuste assim!",
  ui_story_31170601_14_dialog_content = "Sabe, o nome Gram e \"cair acidentalmente\" não combinam na mesma frase. Por que não se junta a mim?",
  ui_story_31170601_15_dialog_content = "Hã? Espere, não, não me puxe para a água—!",
  ui_story_31170601_16_dialog_content = "Abra os olhos e veja, garoto. Não está nem na altura do joelho.",
  ui_story_31170601_17_dialog_content = "Você está certo... Haha, é bom brincar na água assim às vezes.",
  ui_story_31170601_18_dialog_content = "Eu sabia que você ia gostar.",
  ui_story_31170601_19_dialog_content = "Mas não entenda mal, este é o nosso campo de treinamento natural.",
  ui_story_31170601_20_dialog_content = "Está vendo aquela cachoeira? Vá ficar embaixo dela!",
  ui_story_31170601_21_dialog_content = "Que tipo de treinamento é este?",
  ui_story_31170601_22_dialog_content = "Como soldado da linha de frente, você deve manter a calma e resistir até o fim, não importa o que enfrentar.",
  ui_story_31170601_23_dialog_content = "Manter sua postura sob a cascata em movimento sem se mexer é a melhor maneira de aprimorar essa disciplina.",
  ui_story_31170601_24_dialog_content = "Eu chamo o treinamento de \"Guerreiros Nunca Caem.\"",
  ui_story_31170601_25_dialog_content = "É uma batalha contra a natureza, bem como entre você e eu.",
  ui_story_31170601_26_dialog_content = "Vamos, PlayerName! Quem sair dos pés primeiro será responsável por cozinhar hoje.",
  ui_story_31170601_27_dialog_content = "O quê? Mas eu estava desejando sua comida e foi por isso que concordei com o treinamento!",
  ui_story_31170601_28_dialog_content = "Então você acha que não tem nenhuma chance de me derrotar?",
  ui_story_31170601_29_option_content = "De alguma forma, vou me dar uma chance!",
  ui_story_31170601_30_dialog_content = "Eu tenho que acreditar que há uma chance, por menor que seja. Caso contrário, não vou te vencer de jeito nenhum!",
  ui_story_31170601_31_option_content = "Isso porque você é muito forte para mim!",
  ui_story_31170601_32_dialog_content = "Mesmo assim, vou tentar.",
  ui_story_31170601_33_dialog_content = "Vou experimentar a sua comida!",
  ui_story_31170601_34_dialog_content = "<color=#e8d9bb>Splish, splash—</color>",
  ui_story_31170601_35_dialog_content = "Ah! O impacto é maior do que eu pensava...",
  ui_story_31170601_36_dialog_content = "Estou quase... no meu limite...",
  ui_story_31170601_37_dialog_content = "No, just hang on! I'm not going down yet—",
  ui_story_31170601_38_dialog_content = "<size=45>Not going down—Aaaaahhh!</size>",
  ui_story_31170601_39_dialog_content = "<size=45>NOOOO—</size>",
  ui_story_31170601_40_dialog_content = "<size=45>Aaaaahhh—</size>",
  ui_story_31170601_41_dialog_content = "<size=45><color=#e8d9bb>Respingo!</color></size>",
  ui_story_31170601_42_dialog_content = "Hahaha! Nada mal, garoto, você aguentou muito mais tempo do que eu esperava.",
  ui_story_31170601_43_dialog_content = "(Como é que o Gram ainda consegue ficar de pé como uma parede na cachoeira depois de tanto tempo?)",
  ui_story_31170601_44_dialog_content = "(Suspiro, era de se esperar, mesmo. Eu nem estou na mesma liga que ele...)",
  ui_story_31170601_45_dialog_content = "Tudo bem, o jantar está em suas mãos agora!",
  ui_story_31170601_46_dialog_content = "Esse treinamento é muito difícil para mim. É impossível eu vencer sem as vantagens físicas e de força que você possui.",
  ui_story_31170601_47_dialog_content = "PlayerName, você esteve na linha de frente de Illumina, então sabe que temos caras magrelos no exército.",
  ui_story_31170601_48_dialog_content = "E quando eles lutaram, lutaram tão bem quanto eu. Sabe por quê?",
  ui_story_31170601_49_dialog_content = "... Sim, Gram, eu sei o que você quer dizer. Não vou dar mais desculpas.",
  ui_story_31170601_50_dialog_content = "Você sempre encontra a origem de um problema no menor tempo possível, e foi por isso que concordei em levá-lo para o treinamento.",
  ui_story_31170601_51_dialog_content = "Desde que me tornei instrutor, tenho visto cada vez mais jovens de qualidade.",
  ui_story_31170601_52_dialog_content = "Por sua vez, farei exigências mais difíceis do que antes, então é melhor você dar o seu melhor!",
  ui_story_31170601_53_dialog_content = "Eu quase me esqueci que você é o instrutor dos novos recrutas agora!",
  ui_story_31170601_54_dialog_content = "Não é de admirar que há algo diferente em você... O que está acontecendo?",
  ui_story_31170601_55_dialog_content = "Está interessado?",
  ui_story_31170601_56_dialog_content = "Então vá fazer o jantar agora. Certifique-se de fazer o teste de condicionamento físico que eu te mostrei antes.",
  ui_story_31170601_57_dialog_content = "Teste de condicionamento físico? Você quer dizer a rotina de exercícios antes de cozinhar?",
  ui_story_31170601_58_dialog_content = "Não consigo escapar do seu regime mesmo quando perco, eu vejo...",
  ui_story_31170601_59_dialog_content = "<color=#e8d9bb>Some time later</color>",
  ui_story_31170601_60_dialog_content = "*arroto*",
  ui_story_31170601_61_dialog_content = "Eu não esperava que saborear comida refinada na natureza fosse tão prazeroso.",
  ui_story_31170601_62_dialog_content = "É um prazer duplo nos níveis espiritual e físico que você obtém apenas depois de colocar todo o seu esforço no treinamento.",
  ui_story_31170601_63_dialog_content = "Então, que tal sair comigo mais vezes?",
  ui_story_31170601_64_dialog_content = "Com isso, você realmente quer dizer sair e treinar com você, certo?",
  ui_story_31170601_65_dialog_content = "Ah, certo, Gram, falando nisso, aconteceu algo interessante?",
  ui_story_31170601_66_dialog_content = "Eu te contei o que mais ficou na minha cabeça. Quanto ao resto...",
  ui_story_31170601_67_dialog_content = "Os superiores reformularam o equipamento regular de todos novamente. Revy foi em sua própria missão. Ansia finalmente descobriu o interruptor para o alto-falante...",
  ui_story_31170601_68_dialog_content = "E eu, acabei entendendo a escolha que Brent fez.",
  ui_story_31170601_69_dialog_content = "Ver todos esses jovens que conheço crescendo tão rápido é bom. Estou mais feliz e orgulhoso do que vencer uma batalha.",
