  ui_story_31170601_72_dialog_content = "No meu caso ou no caso de Brent, nós velhos rabugentos vivemos o suficiente para não ter nenhum arrependimento em nos sacrificar.",
  ui_story_31170601_73_dialog_content = "Mas cada um dos novos recrutas é tão limpo quanto um lençol novo.",
  ui_story_31170601_74_dialog_content = "Não suporto ver esses jovens perdendo suas vidas... Sabe, Brent me repreenderia por pensar assim.",
  ui_story_31170601_75_dialog_content = "Mas o que você pode fazer, além de ser resistente, e então ainda mais resistente quando eu treiná-los?",
  ui_story_31170601_76_dialog_content = "Transforme os novatos em guerreiros antes de irem para o campo de batalha, para que não precisem fazer sacrifícios desnecessários.",
  ui_story_31170601_77_dialog_content = "Entendo agora que você tinha boas intenções... Mas já pensou em voltar para a frente?",
  ui_story_31170601_78_dialog_content = "Com sua invencibilidade e indomabilidade, você pode facilmente se tornar um exemplo para os soldados e até mesmo uma figura à altura dos comandantes!",
  ui_story_31170601_79_dialog_content = "Tudo bem. Jurei há muito tempo terminar o que Brent não conseguiu. E...",
  ui_story_31170601_80_dialog_content = "\"Guerreiros nunca caem\" não significa um soldado sempre invencível e indomável.",
  ui_story_31170601_81_dialog_content = "Mas você também não é um?",
  ui_story_31170601_82_dialog_content = "Sou um auroriano mortal com minhas próprias fraquezas também. Guerreiros verdadeiramente invencíveis e indomáveis não existem.",
  ui_story_31170601_83_dialog_content = "Mas \"guerreiros nunca caem\" não é um slogan que eu uso para enganar você.",
  ui_story_31170601_84_dialog_content = "A pequena imagem é que talvez milhares e milhares de guerreiros acabem caindo em batalha.",
